<div class="admin-card card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Plantilla</th><th>Archivo</th><th>Descargas</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody>
<?php foreach ($templates as $template): ?><tr><td><strong><?= e((string) $template['title']) ?></strong><br><small class="text-muted">/<?= e((string) $template['slug']) ?></small></td><td><?= e((string) $template['original_file_name']) ?><br><small class="text-muted"><?= e((string) $template['file_mime']) ?></small></td><td><?= (int) $template['download_count'] ?></td><td><?= ($template['status'] ?? '') === 'active' ? 'Visible' : 'Oculta' ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?= e(url('admin/plantillas/' . (int) $template['id'] . '/editar')) ?>">Editar</a><form method="post" action="<?= e(url('admin/plantillas/' . (int) $template['id'])) ?>" class="d-inline"><?= csrf_field() ?><input type="hidden" name="_method" value="DELETE"><button class="btn btn-sm btn-outline-danger" type="submit" onclick="return confirm('La plantilla dejará de estar disponible para descarga. El archivo se conserva 30 días por si necesitas recuperarlo. ¿Continuar?');">Papelera</button></form></td></tr><?php endforeach; ?>
